1	/**
2	 * Unit tests for flush-log.ts — flushLog.
3	 *
4	 * Covers the thin-pack race fix (issue #131):
5	 *   1. Step 1 uses checkout -B <branch> origin/<branch> (not plain checkout)
6	 *   2. Only one git fetch is issued (no second fetch before push)
7	 *   3. git rebase is never called
8	 *   4. Push is called exactly once, directly after commit
9	 *   5. log_flush_failed is emitted and no exception escapes on git failure
10	 *   6. Log file contains run_started, stdout content, and run_ended entries
11	 *   7. Stdout is redacted before writing
12	 *   8. SSH key is wired into GIT_SSH_COMMAND when provided
13	 */
14	
15	import { describe, it, expect, vi, afterEach } from "vitest";
16	import {
17	  mkdtempSync,
18	  mkdirSync,
19	  readFileSync,
20	  rmSync,
21	} from "node:fs";
22	import { tmpdir } from "node:os";
23	import { join } from "node:path";
24	import { execSync } from "node:child_process";
25	import { flushLog } from "./flush-log.js";
26	
27	// ── Mock node:child_process ───────────────────────────────────────────────────
28	
29	vi.mock("node:child_process", async (importOriginal) => {
30	  const actual = await importOriginal<typeof import("node:child_process")>();
31	  return { ...actual, execSync: vi.fn() };
32	});
33	
34	// ── Fixtures ──────────────────────────────────────────────────────────────────
35	
36	const FEATURE_ID = "test-feature";
37	const TASK_ID = "T5";
38	const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
39	const RUN_START_ISO = "2026-05-12T10:00:00.000Z";
40	const GIT_AUTHOR_EMAIL = "agent@test.com";
41	const GIT_AUTHOR_NAME = "Test Agent";
42	
43	const tmpDirs: string[] = [];
44	
45	function makeTmpDir(): string {
46	  const dir = mkdtempSync(join(tmpdir(), "flush-log-unit-"));
47	  tmpDirs.push(dir);
48	  return dir;
49	}
50	
51	afterEach(() => {
52	  while (tmpDirs.length) {
53	    const d = tmpDirs.pop()!;
54	    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
55	  }
56	  vi.clearAllMocks();
57	});
58	
59	function callFlushLog(
60	  wsRoot: string,
61	  opts: { stdout?: string; sshKeyPath?: string; outcome?: string } = {},
62	  emit: (e: Record<string, unknown>) => void = () => {},
63	): void {
64	  flushLog(
65	    wsRoot,
66	    FEATURE_ID,
67	    TASK_ID,
68	    TASK_BRANCH,
69	    RUN_START_ISO,
70	    GIT_AUTHOR_EMAIL,
71	    GIT_AUTHOR_NAME,
72	    opts.stdout ?? "",
73	    opts.outcome ?? "passed",
74	    opts.sshKeyPath,
75	    emit,
76	  );
77	}
78	
79	// ── 1. checkout -B pattern ────────────────────────────────────────────────────
80	
81	describe("flushLog — git checkout pattern", () => {
82	  it("uses checkout -B <branch> origin/<branch> not plain checkout", () => {
83	    const wsRoot = makeTmpDir();
84	    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
85	
86	    callFlushLog(wsRoot);
87	
88	    const calls = vi.mocked(execSync).mock.calls.map(([cmd]) => String(cmd));
89	    const checkoutCall = calls.find((c) => c.includes("checkout") && !c.includes("checkout -- ."));
90	    expect(checkoutCall).toBeDefined();
91	    expect(checkoutCall).toContain(`checkout -B "${TASK_BRANCH}" "origin/${TASK_BRANCH}"`);
92	    expect(checkoutCall).not.toMatch(/checkout "feature\//); // no plain checkout of branch
93	  });
94	});
95	
96	// ── 2. Single fetch only ──────────────────────────────────────────────────────
97	
98	describe("flushLog — single fetch, no second fetch", () => {
99	  it("issues exactly one git fetch call", () => {
100	    const wsRoot = makeTmpDir();
101	    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
102	
103	    callFlushLog(wsRoot);
104	
105	    const fetchCalls = vi.mocked(execSync).mock.calls.filter(([cmd]) =>
106	      String(cmd).includes("fetch origin"),
107	    );
108	    expect(fetchCalls).toHaveLength(1);
109	  });
110	});
111	
112	// ── 3. No rebase ─────────────────────────────────────────────────────────────
113	
114	describe("flushLog — no git rebase", () => {
115	  it("never calls git rebase", () => {
116	    const wsRoot = makeTmpDir();
117	    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
118	
119	    callFlushLog(wsRoot);
120	
121	    const rebaseCall = vi.mocked(execSync).mock.calls.find(([cmd]) =>
122	      String(cmd).includes("rebase"),
123	    );
124	    expect(rebaseCall).toBeUndefined();
125	  });
126	});
127	
128	// ── 4. Single push directly after commit ─────────────────────────────────────
129	
130	describe("flushLog — push directly after commit", () => {
131	  it("calls push exactly once", () => {
132	    const wsRoot = makeTmpDir();
133	    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
134	
135	    callFlushLog(wsRoot);
136	
137	    const pushCalls = vi.mocked(execSync).mock.calls.filter(([cmd]) =>
138	      String(cmd).includes("push origin"),
139	    );
140	    expect(pushCalls).toHaveLength(1);
141	  });
142	
143	  it("push comes immediately after commit — no fetch between them", () => {
144	    const wsRoot = makeTmpDir();
145	    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
146	
147	    callFlushLog(wsRoot);
148	
149	    const cmds = vi.mocked(execSync).mock.calls.map(([cmd]) => String(cmd));
150	    const commitIdx = cmds.findIndex((c) => c.includes("commit"));
151	    const pushIdx = cmds.findIndex((c) => c.includes("push origin"));
152	    expect(commitIdx).toBeGreaterThan(-1);
153	    expect(pushIdx).toBe(commitIdx + 1);
154	  });
155	});
156	
157	// ── 5. log_flush_failed on error ─────────────────────────────────────────────
158	
159	describe("flushLog — error handling", () => {
160	  it("emits log_flush_failed when fetch throws", () => {
161	    const wsRoot = makeTmpDir();
162	    vi.mocked(execSync).mockImplementationOnce(() => { throw new Error("fetch failed"); });
163	    const events: Record<string, unknown>[] = [];
164	
165	    callFlushLog(wsRoot, {}, (e) => events.push(e));
166	
167	    expect(events).toHaveLength(1);
168	    expect(events[0].type).toBe("log_flush_failed");
169	    expect(events[0].task_id).toBe(TASK_ID);
170	    expect(events[0].feature_id).toBe(FEATURE_ID);
171	    expect(String(events[0].details)).toContain("fetch failed");
172	  });
173	
174	  it("emits log_flush_failed when push throws and does not rethrow", () => {
175	    const wsRoot = makeTmpDir();
176	    // fetch, checkout --, checkout -B, add, commit all succeed; push throws
177	    vi.mocked(execSync)
178	      .mockReturnValueOnce(Buffer.from("")) // fetch
179	      .mockReturnValueOnce(Buffer.from("")) // checkout --
180	      .mockReturnValueOnce(Buffer.from("")) // checkout -B
181	      .mockReturnValueOnce(Buffer.from("")) // add
182	      .mockReturnValueOnce(Buffer.from("")) // commit
183	      .mockImplementationOnce(() => { throw new Error("push rejected"); });
184	    const events: Record<string, unknown>[] = [];
185	
186	    expect(() => callFlushLog(wsRoot, {}, (e) => events.push(e))).not.toThrow();
187	    expect(events.some((e) => e.type === "log_flush_failed")).toBe(true);
188	    expect(String(events.find((e) => e.type === "log_flush_failed")!.details)).toContain("push rejected");
189	  });
190	
191	  it("does not emit log_flush_failed on success", () => {
192	    const wsRoot = makeTmpDir();
193	    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
194	    const events: Record<string, unknown>[] = [];
195	
196	    callFlushLog(wsRoot, {}, (e) => events.push(e));
197	
198	    expect(events.filter((e) => e.type === "log_flush_failed")).toHaveLength(0);
199	  });
200	});
201	
202	// ── 6. Log file contents ──────────────────────────────────────────────────────
203	
204	describe("flushLog — log file contents", () => {
205	  it("writes run_started and run_ended entries to the log file", () => {
206	    const wsRoot = makeTmpDir();
207	    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
208	
209	    callFlushLog(wsRoot, { outcome: "passed" });
210	
211	    const safeIso = RUN_START_ISO.replace(/[:.]/g, "-");
212	    const logPath = join(wsRoot, "docs", "features", FEATURE_ID, "logs", TASK_ID, `${safeIso}.jsonl`);
213	    const lines = readFileSync(logPath, "utf-8").trim().split("\n").map((l) => JSON.parse(l));
214	
215	    expect(lines[0].type).toBe("run_started");
216	    expect(lines[0].at).toBe(RUN_START_ISO);
217	    expect(lines[0].by).toBe(GIT_AUTHOR_EMAIL);
218	
219	    const ended = lines.find((l) => l.type === "run_ended");
220	    expect(ended).toBeDefined();
221	    expect(ended.details.outcome).toBe("passed");
222	  });
223	
224	  it("appends stdout between run_started and run_ended", () => {
225	    const wsRoot = makeTmpDir();
226	    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
227	    const stdout = '{"type":"assistant","message":{"content":[{"type":"text","text":"hello"}]}}';
228	
229	    callFlushLog(wsRoot, { stdout });
230	
231	    const safeIso = RUN_START_ISO.replace(/[:.]/g, "-");
232	    const logPath = join(wsRoot, "docs", "features", FEATURE_ID, "logs", TASK_ID, `${safeIso}.jsonl`);
233	    const content = readFileSync(logPath, "utf-8");
234	    expect(content).toContain("hello");
235	  });
236	
237	  it("omits stdout section when stdout is empty", () => {
