/**
 * Unit tests for flush-log.ts — flushLog.
 *
 * Covers the thin-pack race fix (issue #131):
 *   1. Step 1 uses checkout -B <branch> origin/<branch> (not plain checkout)
 *   2. Only one git fetch is issued (no second fetch before push)
 *   3. git rebase is never called
 *   4. Push is called exactly once, directly after commit
 *   5. log_flush_failed is emitted and no exception escapes on git failure
 *   6. Log file contains run_started, stdout content, and run_ended entries
 *   7. Stdout is redacted before writing
 *   8. SSH key is wired into GIT_SSH_COMMAND when provided
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync } from "node:child_process";
import { flushLog } from "./flush-log.js";

// ── Mock node:child_process ───────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const TASK_ID = "T5";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const RUN_START_ISO = "2026-05-12T10:00:00.000Z";
const GIT_AUTHOR_EMAIL = "agent@test.com";
const GIT_AUTHOR_NAME = "Test Agent";

const tmpDirs: string[] = [];

function makeTmpDir(): string {
  const dir = mkdtempSync(join(tmpdir(), "flush-log-unit-"));
  tmpDirs.push(dir);
  return dir;
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
});

function callFlushLog(
  wsRoot: string,
  opts: { stdout?: string; sshKeyPath?: string; outcome?: string } = {},
  emit: (e: Record<string, unknown>) => void = () => {},
): void {
  flushLog(
    wsRoot,
    FEATURE_ID,
    TASK_ID,
    TASK_BRANCH,
    RUN_START_ISO,
    GIT_AUTHOR_EMAIL,
    GIT_AUTHOR_NAME,
    opts.stdout ?? "",
    opts.outcome ?? "passed",
    opts.sshKeyPath,
    emit,
  );
}

// ── 1. checkout -B pattern ────────────────────────────────────────────────────

describe("flushLog — git checkout pattern", () => {
  it("uses checkout -B <branch> origin/<branch> not plain checkout", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));

    callFlushLog(wsRoot);

    const calls = vi.mocked(execSync).mock.calls.map(([cmd]) => String(cmd));
    const checkoutCall = calls.find((c) => c.includes("checkout") && !c.includes("checkout -- ."));
    expect(checkoutCall).toBeDefined();
    expect(checkoutCall).toContain(`checkout -B "${TASK_BRANCH}" "origin/${TASK_BRANCH}"`);
    expect(checkoutCall).not.toMatch(/checkout "feature\//); // no plain checkout of branch
  });
});

// ── 2. Single fetch only ──────────────────────────────────────────────────────

describe("flushLog — single fetch, no second fetch", () => {
  it("issues exactly one git fetch call", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));

    callFlushLog(wsRoot);

    const fetchCalls = vi.mocked(execSync).mock.calls.filter(([cmd]) =>
      String(cmd).includes("fetch origin"),
    );
    expect(fetchCalls).toHaveLength(1);
  });
});

// ── 3. No rebase ─────────────────────────────────────────────────────────────

describe("flushLog — no git rebase", () => {
  it("never calls git rebase", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));

    callFlushLog(wsRoot);

    const rebaseCall = vi.mocked(execSync).mock.calls.find(([cmd]) =>
      String(cmd).includes("rebase"),
    );
    expect(rebaseCall).toBeUndefined();
  });
});

// ── 4. Single push directly after commit ─────────────────────────────────────

describe("flushLog — push directly after commit", () => {
  it("calls push exactly once", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));

    callFlushLog(wsRoot);

    const pushCalls = vi.mocked(execSync).mock.calls.filter(([cmd]) =>
      String(cmd).includes("push origin"),
    );
    expect(pushCalls).toHaveLength(1);
  });

  it("push comes immediately after commit — no fetch between them", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));

    callFlushLog(wsRoot);

    const cmds = vi.mocked(execSync).mock.calls.map(([cmd]) => String(cmd));
    const commitIdx = cmds.findIndex((c) => c.includes("commit"));
    const pushIdx = cmds.findIndex((c) => c.includes("push origin"));
    expect(commitIdx).toBeGreaterThan(-1);
    expect(pushIdx).toBe(commitIdx + 1);
  });
});

// ── 5. log_flush_failed on error ─────────────────────────────────────────────

describe("flushLog — error handling", () => {
  it("emits log_flush_failed when fetch throws", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockImplementationOnce(() => { throw new Error("fetch failed"); });
    const events: Record<string, unknown>[] = [];

    callFlushLog(wsRoot, {}, (e) => events.push(e));

    expect(events).toHaveLength(1);
    expect(events[0].type).toBe("log_flush_failed");
    expect(events[0].task_id).toBe(TASK_ID);
    expect(events[0].feature_id).toBe(FEATURE_ID);
    expect(String(events[0].details)).toContain("fetch failed");
  });

  it("emits log_flush_failed when push throws and does not rethrow", () => {
    const wsRoot = makeTmpDir();
    // fetch, checkout --, checkout -B, add, commit all succeed; push throws
    vi.mocked(execSync)
      .mockReturnValueOnce(Buffer.from("")) // fetch
      .mockReturnValueOnce(Buffer.from("")) // checkout --
      .mockReturnValueOnce(Buffer.from("")) // checkout -B
      .mockReturnValueOnce(Buffer.from("")) // add
      .mockReturnValueOnce(Buffer.from("")) // commit
      .mockImplementationOnce(() => { throw new Error("push rejected"); });
    const events: Record<string, unknown>[] = [];

    expect(() => callFlushLog(wsRoot, {}, (e) => events.push(e))).not.toThrow();
    expect(events.some((e) => e.type === "log_flush_failed")).toBe(true);
    expect(String(events.find((e) => e.type === "log_flush_failed")!.details)).toContain("push rejected");
  });

  it("does not emit log_flush_failed on success", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
    const events: Record<string, unknown>[] = [];

    callFlushLog(wsRoot, {}, (e) => events.push(e));

    expect(events.filter((e) => e.type === "log_flush_failed")).toHaveLength(0);
  });
});

// ── 6. Log file contents ──────────────────────────────────────────────────────

describe("flushLog — log file contents", () => {
  it("writes run_started and run_ended entries to the log file", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));

    callFlushLog(wsRoot, { outcome: "passed" });

    const safeIso = RUN_START_ISO.replace(/[:.]/g, "-");
    const logPath = join(wsRoot, "docs", "features", FEATURE_ID, "logs", TASK_ID, `${safeIso}.jsonl`);
    const lines = readFileSync(logPath, "utf-8").trim().split("\n").map((l) => JSON.parse(l));

    expect(lines[0].type).toBe("run_started");
    expect(lines[0].at).toBe(RUN_START_ISO);
    expect(lines[0].by).toBe(GIT_AUTHOR_EMAIL);

    const ended = lines.find((l) => l.type === "run_ended");
    expect(ended).toBeDefined();
    expect(ended.details.outcome).toBe("passed");
  });

  it("appends stdout between run_started and run_ended", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
    const stdout = '{"type":"assistant","message":{"content":[{"type":"text","text":"hello"}]}}';

    callFlushLog(wsRoot, { stdout });

    const safeIso = RUN_START_ISO.replace(/[:.]/g, "-");
    const logPath = join(wsRoot, "docs", "features", FEATURE_ID, "logs", TASK_ID, `${safeIso}.jsonl`);
    const content = readFileSync(logPath, "utf-8");
    expect(content).toContain("hello");
  });

  it("omits stdout section when stdout is empty", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));

    callFlushLog(wsRoot, { stdout: "" });

    const safeIso = RUN_START_ISO.replace(/[:.]/g, "-");
    const logPath = join(wsRoot, "docs", "features", FEATURE_ID, "logs", TASK_ID, `${safeIso}.jsonl`);
    const lines = readFileSync(logPath, "utf-8").trim().split("\n");
    // Only run_started and run_ended
    expect(lines).toHaveLength(2);
  });
});

// ── 7. Stdout redaction ───────────────────────────────────────────────────────

describe("flushLog — stdout redaction", () => {
  it("redacts secrets from stdout before writing to log", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
    const stdout = 'token=[REDACTED:github-pat] some text';

    callFlushLog(wsRoot, { stdout });

    const safeIso = RUN_START_ISO.replace(/[:.]/g, "-");
    const logPath = join(wsRoot, "docs", "features", FEATURE_ID, "logs", TASK_ID, `${safeIso}.jsonl`);
    const content = readFileSync(logPath, "utf-8");
    expect(content).not.toContain("[REDACTED:github-pat]");
  });
});

// ── 8. SSH key wiring ─────────────────────────────────────────────────────────

describe("flushLog — SSH key wiring", () => {
  it("sets GIT_SSH_COMMAND when sshKeyPath is provided", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));

    callFlushLog(wsRoot, { sshKeyPath: "/home/user/.ssh/id_rsa" });

    const [, opts] = vi.mocked(execSync).mock.calls[0];
    const env = (opts as { env?: Record<string, string> })?.env ?? {};
    expect(env["GIT_SSH_COMMAND"]).toContain("/home/user/.ssh/id_rsa");
  });

  it("does not set GIT_SSH_COMMAND when sshKeyPath is undefined", () => {
    const wsRoot = makeTmpDir();
    vi.mocked(execSync).mockReturnValue(Buffer.from(""));

    // Ensure GIT_SSH_COMMAND is absent from the test environment so the
    // assertion is not contaminated by the executor container's default key.
    const saved = process.env["GIT_SSH_COMMAND"];
    delete process.env["GIT_SSH_COMMAND"];
    try {
      callFlushLog(wsRoot, { sshKeyPath: undefined });
    } finally {
      if (saved !== undefined) process.env["GIT_SSH_COMMAND"] = saved;
    }

    const [, opts] = vi.mocked(execSync).mock.calls[0];
    const env = (opts as { env?: Record<string, string> })?.env ?? {};
    expect(env["GIT_SSH_COMMAND"]).toBeUndefined();
  });
});

