/**
 * Best-effort log flush to the management repo task branch.
 *
 * Mirrors the mutateTaskYamlDirect pattern: checkout -B to force-reset to
 * the fetched origin tip before writing, so the push is always fast-forward
 * and no second fetch + rebase is required (fixes thin-pack race with syncRepo,
 * issue #131).
 */

import { execSync } from "node:child_process";
import { mkdirSync, appendFileSync } from "node:fs";
import { join } from "node:path";
import { redactSecrets } from "./redact-secrets.js";

export function flushLog(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  taskBranch: string,
  runStartIso: string,
  gitAuthorEmail: string,
  gitAuthorName: string,
  stdout: string,
  outcome: string,
  sshKeyPath: string | undefined,
  emit: (event: Record<string, unknown>) => void,
): void {
  try {
    const safeIso = runStartIso.replace(/[:.]/g, "-");
    const logFilename = `${safeIso}.jsonl`;
    const relLogPath = join("docs", "features", featureId, "logs", taskId, logFilename);
    const logPath = join(workspaceRoot, relLogPath);

    const env = {
      ...process.env,
      GIT_AUTHOR_NAME: gitAuthorName,
      GIT_AUTHOR_EMAIL: gitAuthorEmail,
      GIT_COMMITTER_NAME: gitAuthorName,
      GIT_COMMITTER_EMAIL: gitAuthorEmail,
      GIT_SSH_COMMAND: sshKeyPath ? `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new` : undefined,
    };
    const gitOpts = { env, stdio: "pipe" as const, timeout: 30_000 };

    // Step 1: Move to the task branch tip BEFORE writing any files.
    // Use checkout -B to force-reset to the fetched origin tip — mirrors mutateTaskYamlDirect.
    // This guarantees fully-materialized objects (no thin-pack gaps) and eliminates the
    // need for a second fetch + rebase, which races with syncRepo's periodic git fetch.
    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, gitOpts);
    execSync(`git -C "${workspaceRoot}" checkout -- .`, gitOpts);
    execSync(`git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);

    // Step 2: Write the log file (directory may not exist on this branch yet).
    const logsDir = join(workspaceRoot, "docs", "features", featureId, "logs", taskId);
    mkdirSync(logsDir, { recursive: true });
    appendFileSync(logPath, JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n");
    if (stdout) {
      const safe = redactSecrets(stdout);
      appendFileSync(logPath, safe.endsWith("\n") ? safe : safe + "\n");
    }
    appendFileSync(logPath, JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n");

    // Step 3: Commit and push. No second fetch or rebase needed — we already
    // started from the exact origin tip, so the push is always fast-forward.
    // A rejected push (log_flush_failed) is acceptable; log is telemetry only.
    execSync(`git -C "${workspaceRoot}" add "${relLogPath}"`, gitOpts);
    execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
    execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
  } catch (e) {
    emit({ type: "log_flush_failed", task_id: taskId, feature_id: featureId, details: String(e) });
  }
}

